import {useState} from "react";
import {Document, Page, pdfjs} from "react-pdf";
import "react-pdf/dist/Page/AnnotationLayer.css";
import "react-pdf/dist/Page/TextLayer.css";
import orangeManPdf from "../assets/writings/Orange Man.pdf";
import SubjugationPdf from "../assets/writings/Subjugation of Nature.pdf";
import ProfessionPdf from "../assets/writings/Editable ENG II_ Initial.pdf";
import Mores from "../assets/writings/Copy of Research Essay.pdf";

// Configure PDF.js worker
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

// Essay collection with titles and files
const essays = [
    { title: "Orange Man", file: orangeManPdf, description: "Reflection on the Charge of the Light Brigade by Tennyson. Exploring the topics of discipline, loyalty and officer responsibility." },
    { title: "Subjugation of Nature", file: SubjugationPdf, description: "Explration of the conflict between human and nature in the context of the Enlightenment and Romanticism." },
    { title: "Professional Writing", file: ProfessionPdf, description: "A reflection on what it means to be a professional." },
    { title: "Research Essay", file: Mores, description: "A research essay on work ethics." }
];

function Writings() {

    const [numPages, setNumPages] = useState(null);
    const [selectedEssay, setSelectedEssay] = useState(null);

    function onDocumentLoadSuccess({numPages}) {
        setNumPages(numPages);
    }

    function handleBack() {
        setSelectedEssay(null);
        setNumPages(null);
    }

    // Show essay selection if none selected
    if (!selectedEssay) {
        return (
            <div style={{ padding: "2rem" }}>
                <h1 style={{ 
                    fontSize: "2.5rem", 
                    marginBottom: "0.5rem",
                    background: "linear-gradient(90deg, #00d9ff, #a78bfa)",
                    WebkitBackgroundClip: "text",
                    WebkitTextFillColor: "transparent"
                }}>
                    Writings
                </h1>
                <p style={{ 
                    color: "#888", 
                    marginBottom: "3rem",
                    fontSize: "1.1rem",
                    fontStyle: "italic"
                }}>
                    A collection of essays and reflections
                </p>
                <div style={{
                    display: "grid",
                    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
                    gap: "1.5rem",
                    maxWidth: "900px",
                    margin: "0 auto"
                }}>
                    {essays.map((essay, index) => (
                        <div
                            key={index}
                            onClick={() => setSelectedEssay(essay)}
                            style={{
                                padding: "1.5rem",
                                backgroundColor: "rgba(26, 26, 46, 0.8)",
                                border: "1px solid #2a2a4a",
                                borderRadius: "12px",
                                cursor: "pointer",
                                transition: "all 0.3s ease",
                                textAlign: "left",
                                backdropFilter: "blur(10px)"
                            }}
                            onMouseOver={(e) => {
                                e.currentTarget.style.transform = "translateY(-4px)";
                                e.currentTarget.style.borderColor = "#00d9ff";
                                e.currentTarget.style.boxShadow = "0 8px 30px rgba(0, 217, 255, 0.15)";
                            }}
                            onMouseOut={(e) => {
                                e.currentTarget.style.transform = "translateY(0)";
                                e.currentTarget.style.borderColor = "#2a2a4a";
                                e.currentTarget.style.boxShadow = "none";
                            }}
                        >
                            <h3 style={{ 
                                color: "#00d9ff", 
                                margin: "0 0 0.75rem 0",
                                fontSize: "1.25rem",
                                fontWeight: "600"
                            }}>
                                {essay.title}
                            </h3>
                            <p style={{ 
                                color: "#9ca3af", 
                                margin: 0,
                                fontSize: "0.9rem",
                                lineHeight: "1.5"
                            }}>
                                {essay.description}
                            </p>
                            <span style={{
                                display: "inline-block",
                                marginTop: "1rem",
                                color: "#00d9ff",
                                fontSize: "0.85rem",
                                opacity: 0.7
                            }}>
                                Read essay →
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    // Show selected essay
    return (
        <div>
            <h1>Writings</h1>
            <button
                onClick={handleBack}
                style={{
                    padding: "0.5rem 1rem",
                    marginBottom: "1rem",
                    backgroundColor: "#16213e",
                    color: "#00d9ff",
                    border: "1px solid #00d9ff",
                    borderRadius: "4px",
                    cursor: "pointer"
                }}
            >
                ← Back to list
            </button>
            <h2 style={{ color: "#00d9ff", marginBottom: "1rem" }}>{selectedEssay.title}</h2>
            <div style={{
                maxHeight: "70vh",
                overflowY: "auto",
                border: "1px solid #333",
                borderRadius: "8px",
                padding: "1rem",
                margin: "0 auto",
                width: "fit-content"
            }}>
                <Document file={selectedEssay.file} onLoadSuccess={onDocumentLoadSuccess}>
                    {numPages && Array.from({length: numPages}, (_, index) => (
                        <Page key={index + 1} pageNumber={index + 1} width={600} />
                    ))}
                </Document>
            </div>
            <p>{numPages} pages</p>
        </div>
    );
}

export default Writings;